#include "../xsbench-cuda/Simulation.cu"
#include "../xsbench-cuda/XSutils.cu"
#include <vector>
#include <fstream>
#include <algorithm>
__global__ void observe(int n,const int*num,const double*concs,const int*mats,const NuclideGridPoint*grid,const double*energy,const int*idx,long I,long G,int typ,int bins,int M,double*out){int i=blockIdx.x*blockDim.x+threadIdx.x;if(i>=n)return;uint64_t seed=fast_forward_LCG(1070,2*i);double e=LCG_random_double(&seed);int mat=pick_mat(&seed);double macro[5];calculate_macro_xs(e,mat,I,G,num,concs,energy,idx,grid,mats,macro,typ,bins,M);out[7*i]=e;out[7*i+1]=mat;for(int k=0;k<5;k++)out[7*i+2+k]=macro[k];}
void ck(cudaError_t e){if(e!=cudaSuccess){fprintf(stderr,"%s\n",cudaGetErrorString(e));exit(2);}}
std::vector<double> load(const char*f){std::ifstream in(f,std::ios::binary|std::ios::ate);if(!in)exit(3);size_t n=in.tellg();if(n%8)exit(3);in.seekg(0);std::vector<double>v(n/8);in.read((char*)v.data(),n);if(!in)exit(3);return v;}
void append(std::vector<double>&a,double v){a.push_back(v);}void append(std::vector<double>&a,int v){a.push_back(v);}void append(std::vector<double>&a,NuclideGridPoint v){a.insert(a.end(),{v.energy,v.total_xs,v.elastic_xs,v.absorbtion_xs,v.fission_xs,v.nu_fission_xs});}
template<class T>struct Buf{std::vector<T>h;T*base,*d;Buf(std::vector<T>v,T guard){h.assign(v.size()+128,guard);std::copy(v.begin(),v.end(),h.begin()+64);ck(cudaMalloc(&base,h.size()*sizeof(T)));d=base+64;reset();}void reset(){ck(cudaMemcpy(base,h.data(),h.size()*sizeof(T),cudaMemcpyHostToDevice));}void capture(std::vector<double>&a){std::vector<T>v(h.size());ck(cudaMemcpy(v.data(),base,v.size()*sizeof(T),cudaMemcpyDeviceToHost));for(auto x:v)append(a,x);}};
struct Case{int typ,I,G,N,reps,bins,M;Buf<int>*num,*mats,*idx,*out;Buf<double>*concs,*energy,*obs;Buf<NuclideGridPoint>*grid;};
int main(){auto pre=load(FIXTURE),gold=load(ORACLE);std::ifstream f(KINDS,std::ios::binary);std::vector<unsigned char>kind(gold.size());f.read((char*)kind.data(),kind.size());if(!f)return 3;size_t pos=1;std::vector<Case>cs;
 for(int ci=0;ci<6;ci++){Case c;c.typ=pre[pos++];c.I=pre[pos++];c.G=pre[pos++];c.N=pre[pos++];c.reps=pre[pos++];c.bins=pre[pos++];c.M=pre[pos++];int U=pre[pos++],IX=pre[pos++];auto vi=[&](int n){std::vector<int>v(n);for(auto&x:v)x=pre[pos++];return v;};auto vd=[&](int n){std::vector<double>v(n);for(auto&x:v)x=pre[pos++];return v;};c.num=new Buf<int>(vi(12),16384);c.concs=new Buf<double>(vd(12*c.M),16384);c.mats=new Buf<int>(vi(12*c.M),16384);std::vector<NuclideGridPoint>v(c.I*c.G);for(auto&x:v){x={pre[pos],pre[pos+1],pre[pos+2],pre[pos+3],pre[pos+4],pre[pos+5]};pos+=6;}c.grid=new Buf<NuclideGridPoint>(v,{16384,16384,16384,16384,16384,16384});c.energy=new Buf<double>(vd(U),16384);c.idx=new Buf<int>(vi(IX),16384);c.out=new Buf<int>(std::vector<int>(c.N,16384),16384);c.obs=new Buf<double>(std::vector<double>(7*c.N,16384),16384);cs.push_back(c);}if(pos!=pre.size())return 3;
 auto primary=[&](Case&c){lookup<<<(c.N+255)/256,256>>>(c.num->d,c.concs->d,c.mats->d,c.grid->d,c.out->d,c.energy->d,c.idx->d,c.N,c.I,c.G,c.typ,c.bins,c.M);ck(cudaGetLastError());};auto diag=[&](Case&c){observe<<<(c.N+255)/256,256>>>(c.N,c.num->d,c.concs->d,c.mats->d,c.grid->d,c.energy->d,c.idx->d,c.I,c.G,c.typ,c.bins,c.M,c.obs->d);ck(cudaGetLastError());};for(auto&c:cs){primary(c);diag(c);ck(cudaDeviceSynchronize());}
 for(int trial=1;trial<=5;trial++){auto art=pre;std::vector<double>times;for(auto&c:cs){c.out->reset();c.obs->reset();ck(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();for(int it=0;it<c.reps;it++)primary(c);ck(cudaDeviceSynchronize());times.push_back(std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count());diag(c);ck(cudaDeviceSynchronize());c.out->capture(art);c.obs->capture(art);c.num->capture(art);c.concs->capture(art);c.mats->capture(art);c.grid->capture(art);c.energy->capture(art);c.idx->capture(art);}if(art.size()!=pre.size()+gold.size())return 5;bool ok=true;double ma=0;for(size_t i=0;i<gold.size();i++){double x=art[pre.size()+i],e=fabs(x-gold[i]);ok&=std::isfinite(x)&&(kind[i]?x==gold[i]:e<=1e-10+2e-12*fabs(gold[i]));ma=std::max(ma,e);}std::string path=std::string(getenv("STUDY_OUTPUT_DIR")?getenv("STUDY_OUTPUT_DIR"):".")+"/output_trial"+std::to_string(trial)+".bin";std::ofstream out(path,std::ios::binary);out.write((char*)art.data(),art.size()*8);out.close();if(!out)return 6;double total=0;for(auto x:times)total+=x;
 printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.17g,\"max_rel_error\":null,\"timing_region\":\"sum6_source_event_lookup_argmax_kernel_repeats_all_three_grid_methods\",\"jit_excluded\":true,\"internal_repeats\":1,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"},\"path_times_seconds\":[%.17g,%.17g,%.17g,%.17g,%.17g,%.17g],\"source_derived_timed_launches\":15,\"untimed_observer_launches\":6,\"primary_authored_kernels\":1,\"scientific_observer_kernels\":1}\n",trial,total,ok?"true":"false",art.size(),ma,path.c_str(),art.size(),times[0],times[1],times[2],times[3],times[4],times[5]);}}
